class RetailerIndentItem {
  constructor(
    id,
    draft_id,
    wholesaler,
    wholesaler_title,
    wholesaler_receipt,
    wholesaler_receipt_title,
    preparation,
    preparation_title,
    manufacturer,
    manufacturer_title,
    purchased_quantity,
    discount_quantity,
    item_gross_price,
    item_gross_price_total,
    item_discount,
    item_discount_total,
    item_net_price,
    item_net_price_total,
    owner_id,
    manufacture_date,
    expiry_date,
    image
  ) {
    this.id = id;
    this.draft_id = draft_id;
    this.wholesaler = wholesaler;
    this.wholesaler_title = wholesaler_title;
    this.wholesaler_receipt = wholesaler_receipt;
    this.wholesaler_receipt_title = wholesaler_receipt_title;
    this.preparation = preparation;
    this.preparation_title = preparation_title;
    this.manufacturer = manufacturer;
    this.manufacturer_title = manufacturer_title;
    this.purchased_quantity = purchased_quantity;
    this.discount_quantity = discount_quantity;
    this.item_gross_price = item_gross_price;
    this.item_gross_price_total = item_gross_price_total;
    this.item_discount = item_discount;
    this.item_discount_total = item_discount_total;
    this.item_net_price = item_net_price;
    this.item_net_price_total = item_net_price_total;
    this.owner_id = owner_id;
    this.manufacture_date = manufacture_date;
    this.expiry_date = expiry_date;
    this.image = image;
  }
}

export default RetailerIndentItem;
